"""Append matched-study evidence to the offline direction report."""
import json
from experiments.eight_directions.d2_market_prior.study import OUT

def usd(v):return '—' if v is None else f'${v:.6f}'

def run():
    x=json.loads((OUT/'fresh_results.json').read_text());r=json.loads((OUT/'results.json').read_text());s=json.loads((OUT/'spending.json').read_text());lines=['## Fresh matched market-prior prompt study','','The fresh matched study completed '+str(x['attrition']['completed_requests'])+' of '+str(x['attrition']['planned_requests'])+' requests, retaining '+str(x['attrition']['complete_pairs'])+' paired forecast points and '+str(x['attrition']['assessment_match_count'])+' assessment matches. Its incremental-market classification is **'+x['classification']+'**. Invalid outputs are included with the same penalties in both model arms. The market baseline uses precisely the same retained timestamps.','','| Fresh forecast | Brier | Log loss | Valid rate |','|---|---:|---:|---:|']
    for a,m in x['forecast'].items():
        if m is not None:lines.append(f"| {a} | {m['brier']:.6f} | {m['log_loss']:.6f} | {100*m['valid']:.1f}% |")
    lines+=['','| Paired comparison | Brier delta, 95% interval | Log loss delta, 95% interval |','|---|---:|---:|']
    for n,pa in x['paired'].items():
        if pa is None:continue
        b=pa['brier'];l=pa['log_loss'];bi=b['paired_match_bootstrap_95'];li=l['paired_match_bootstrap_95'];lines.append(f"| {n} | {b['mean_delta']:+.6f} [{bi[0]:+.6f}, {bi[1]:+.6f}] | {l['mean_delta']:+.6f} [{li[0]:+.6f}, {li[1]:+.6f}] |")
    a=x['adjustment_cap_audit'];lines+=['','The small-adjustment limit was an instruction, not an output projection. Among '+str(a['valid_treatment_predictions'])+' valid treatment forecasts, '+str(a['violations_over_0_10'])+' exceeded 0.10 absolute change in at least one outcome ('+f"{100*a['violation_rate']:.1f}%"+' of valid treatment forecasts). No prediction was excluded because it violated that instruction. The largest observed absolute adjustment was '+f"{a['max_adjustment']:.6f}"+'. Thus observed cap adherence, forecast improvement and trading performance are distinct findings.','','| Fresh frozen signal | Net P&L | Gross losses | Average win | Average loss | Worst loss | Entry exposure | Max exposure | Turnover | Coverage |','|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
    for n,t in x['trading'].items():
        if t is None:continue
        lines.append('| '+n+' | '+' | '.join(usd(t[k]) for k in ['net_pnl','gross_losses','average_win','average_loss','worst_loss','total_entry_exposure','maximum_match_exposure'])+f" | {t['turnover_shares']:.2f} | {100*t['trading_coverage']:.1f}% |")
    lines+=['| No trade | $0 | $0 | — | — | $0 | $0 | $0 | 0 | 0% |','','Only complete paired decision trajectories contribute to trading: '+str(x['attrition']['full_paired_trajectory_cases'])+' of 99 game-repeat cases. Forecast pairs and trading trajectories have separate completeness rules, each recorded in `fresh_results.json`. The original observed positions are identical across prompts and frozen; they were not generated by these fresh predictions. This is fresh inference but counterfactual frozen-signal P&L, not new closed-loop trading.','','| Paired comparison | Mean P&L delta/game-repeat | 95% interval |','|---|---:|---:|']
    for n,pa in x['paired'].items():
        if pa is None or pa.get('pnl') is None:continue
        q=pa['pnl'];ci=q['paired_match_bootstrap_95'];lines.append(f"| {n} | {usd(q['mean_delta'])} | [{usd(ci[0])}, {usd(ci[1])}] |")
    lines+=['','Fresh usage: '+str(s['paid_requests'])+' completed requests, **'+usd(s['token_cost_estimate_usd'])+'** full-rate token estimate; retained maximum reservations **'+usd(s['reserved_max_usd'])+'** under the $5 cap. Billing evidence: '+str(s.get('billing_evidence_usd'))+'. These figures are not a provider invoice. `fresh_guard.json` confirms that the ledger remained unchanged.','','The matched intervention tests instructions for using a prior the original prompt already exposed. Any advantage over the original prompt alone must still be compared with market-only. The study changes no fitting weights or trading thresholds after observing these results, and makes no claims about protected generalization.','','```sh','PYTHONPATH=. HF_HUB_OFFLINE=1 TRANSFORMERS_OFFLINE=1 /Users/alexkan/Desktop/frontiers/rin-gym-forecast-only/.venv/bin/python -m experiments.eight_directions.d2_market_prior.fresh_analysis','PYTHONPATH=. /Users/alexkan/Desktop/frontiers/rin-gym-forecast-only/.venv/bin/python -m experiments.eight_directions.d2_market_prior.fresh_report','PYTHONPATH=. HF_HUB_OFFLINE=1 TRANSFORMERS_OFFLINE=1 /Users/alexkan/Desktop/frontiers/rin-gym-forecast-only/.venv/bin/python -m experiments.eight_directions.d2_market_prior.verify_fresh','```']
    lines+=['','Both selected variants should stop as candidates for demonstrated market edge on these games. A further discriminating study would freeze the model, prompt and executor and use additional uninspected chronological development games, rather than add repeats or tune thresholds on these 33 games. The protected holdout remains sealed.', '', 'The newest incremental paid-service cap is $5 for the entire task. The orchestrator allowed this existing frozen run to finish because combined reservations remained below that cap. This direction performed no further paid run; `budget_context.json` records the shared cap.']
    body=(OUT/'REPORT.md').read_text();body=body.split('\n## Fresh matched market-prior prompt study')[0];(OUT/'REPORT.md').write_text(body+'\n'+'\n'.join(lines)+'\n')
    r['fresh_status']='complete';r['fresh_classification']=x['classification'];r['fresh_summary']=x['forecast'];r['fresh_attrition']=x['attrition'];r['spending_summary']={k:v for k,v in s.items() if k!='entries'}
    r['overall_classification']='promising' if x['classification']=='promising' else 'negative' if x['classification']=='negative' else 'inconclusive'
    (OUT/'results.json').write_text(json.dumps(r,indent=2)+'\n')
    print('Fresh report appended:',r['overall_classification'])

if __name__=='__main__':run()
